public sealed class CreditSubmissionSqlTests(SqlFixture fixture):CreditRequirementsSqlBase(fixture),IClassFixture<SqlFixture>,IDisposable
{
    private WebApplicationFactory<Program>? staffFactory;
    private Task<HttpClient> Staff(string role)=>base.Staff(role,staffFactory??=sql.Factory.WithWebHostBuilder(_=>{}));
    public void Dispose()=>staffFactory?.Dispose();
    private static string Base(JsonNode accepted)=>"/api/credit/applications/"+Value(accepted["application"]!,"id");
    private static SubmitCreditApplicationInput Input(JsonNode accepted,JsonNode current,string note="Synthetic QA 😀؛ یادداشت خصوصی")=>new(Value(accepted["application"]!,"version"),Value(accepted["consent"]!,"id"),Value(current["published"]!,"id"),Value(current,"version"),"en",note,true);
    private async Task<(JsonNode Accepted,JsonNode Current)> Consent(HttpClient customer,HttpClient finance,bool required=false)
    {
        var current=(await Publish(finance,required?Content():Content()with{Documents=[]}))["current"]!;var app=await Draft(customer);var accepted=await Read(await customer.PostAsJsonAsync("/api/credit/applications/"+Value(app,"id")+"/consents/"+Id(),Acceptance(app,current)));return(accepted,current);
    }
    private static async Task<JsonNode> Wire(HttpResponseMessage response,string name)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");if(Environment.GetEnvironmentVariable("SHOP_CREDIT_SUBMISSION_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,name+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,name+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,cacheControl=response.Headers.CacheControl?.ToString()}));}return JsonNode.Parse(raw)!;}
    }
    [Fact]public async Task ExplicitSubmissionCreatesAnImmutablePrivateSnapshotAndWithdrawalRetainsItsOriginalReceiptWithoutOrdering()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var(c,current)=await Consent(customer,finance);var path=Base(c);var command=Id();var input=Input(c,current);
        var ready=await Wire(await customer.GetAsync(path+"/submission"),"ready");Assert.True(ready["canSubmit"]!.GetValue<bool>());Assert.False(ready["canWithdraw"]!.GetValue<bool>());Assert.Equal(0,ready["requiredDocumentCount"]!.GetValue<int>());
        var submitted=await Wire(await customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input),"submitted");Assert.Equal("Submitted",Value(submitted["application"]!,"state"));Assert.Equal("9007199254740993",Value(submitted["application"]!,"requestedAmountRial"));var subId=Value(submitted["submission"]!,"id");Assert.NotEqual(Value(c["application"]!,"version"),Value(submitted["application"]!,"version"));
        var details=await Wire(await reviewer.GetAsync(path.Replace("/api/credit/","/api/admin/credit/")+"/submissions/"+subId),"reviewer-detail");Assert.Equal(input.Note,Value(details,"note"));Assert.Empty(details["documents"]!.AsArray());Assert.Equal(Value(c["consent"]!,"id"),Value(details["consent"]!,"id"));
        var queue=await Wire(await reviewer.GetAsync("/api/admin/credit/applications?state=Submitted"),"queue");Assert.Contains(queue["items"]!.AsArray(),x=>Value(x!,"id")==Value(c["application"]!,"id"));var staffCapabilities=await Wire(await reviewer.GetAsync(path.Replace("/api/credit/","/api/admin/credit/")+"/submission"),"staff-capabilities");Assert.False(staffCapabilities["canSubmit"]!.GetValue<bool>());Assert.False(staffCapabilities["canWithdraw"]!.GetValue<bool>());
        using(var consent=await customer.PostAsJsonAsync(path+"/consents/"+Id(),Acceptance(submitted["application"]!,current)))Assert.Equal(HttpStatusCode.Conflict,consent.StatusCode);
        var withdrawn=await Read(await customer.PutAsJsonAsync(path+"/cancel/"+Id(),new CancelCreditApplicationInput(Value(submitted["application"]!,"version"))));Assert.Equal("Cancelled",Value(withdrawn["application"]!,"state"));await Publish(finance,Content("later",false));var replay=await Wire(await customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input),"historical-replay");Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(submitted["submission"]!.ToJsonString(),replay["submission"]!.ToJsonString());var receipt=await Wire(await customer.GetAsync(path+"/submissions/commands/"+command),"receipt");Assert.Equal("Submitted",Value(receipt["application"]!,"state"));await Wire(await customer.GetAsync(path+"/submissions/"+subId),"withdrawn-detail");await Wire(await customer.GetAsync(path+"/submissions"),"history");
        await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var id=Value(c["application"]!,"id");var row=await db.Submissions.AsNoTracking().SingleAsync(x=>x.ApplicationId==id);Assert.DoesNotContain(input.Note,Encoding.UTF8.GetString(row.ProtectedNote));Assert.Single(await db.SubmissionCommands.Where(x=>x.ApplicationId==id).ToArrayAsync());Assert.Contains(await db.ApplicationEvents.Where(x=>x.ApplicationId==id).ToArrayAsync(),x=>x.Action=="Withdrawn");Assert.Single(await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.Where(x=>x.Action=="CREDIT_SUBMIT"&&x.ActorId==person.Owner).ToArrayAsync());Assert.Empty(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.ToArrayAsync());Assert.Empty(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Reservations.ToArrayAsync());
    }
    [Fact]public async Task RequiredDocumentsChangedPlanAndNewRequirementsBlockSubmissionAndForeignActorsCannotReadPrivateHistory()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var person=await Customer();using var customer=person.Client;var other=await Customer();using var stranger=other.Client;var(c,current)=await Consent(customer,finance,true);var path=Base(c);var input=Input(c,current);var command=Id();var capabilities=await Wire(await customer.GetAsync(path+"/submission"),"missing-documents");Assert.False(capabilities["canSubmit"]!.GetValue<bool>());Assert.Contains("sample-proof",capabilities["missingDocumentKeys"]!.AsArray().Select(x=>x!.GetValue<string>()));using(var denied=await customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
        foreach(var suffix in new[]{"/submission","/submissions","/submissions/"+Id(),"/submissions/commands/"+command})using(var denied=await stranger.GetAsync(path+suffix))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);
        using(var denied=await stranger.PostAsJsonAsync(path+"/submissions/commands/"+Id(),input))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);using(var denied=await finance.GetAsync(path.Replace("/api/credit/","/api/admin/credit/")+"/submission"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await reviewer.PostAsJsonAsync(path.Replace("/api/credit/","/api/admin/credit/")+"/submissions/commands/"+Id(),input))Assert.Contains(denied.StatusCode,new[]{HttpStatusCode.NotFound,HttpStatusCode.MethodNotAllowed});
        using(var denied=await customer.GetAsync(path+"/submission?ownerId=forged"))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);using(var denied=await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),new{input.ApplicationVersion,input.ConsentId,input.RequirementsRevisionId,input.RequirementsVersion,input.Locale,input.Note,input.ReviewRequested,approved=true}))Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);
        var(c2,current2)=await Consent(customer,finance);var path2=Base(c2);var input2=Input(c2,current2);await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var plan=await db.Plans.SingleAsync(x=>x.Id==Value(c2["application"]!,"planId"));plan.Enabled=false;await db.SaveChangesAsync();}var changed=await Read(await customer.GetAsync(path2+"/submission"));Assert.Contains("credit_plan_changed",changed["blockers"]!.AsArray().Select(x=>x!.GetValue<string>()));using(var denied=await customer.PostAsJsonAsync(path2+"/submissions/commands/"+Id(),input2))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
        var(c3,current3)=await Consent(customer,finance);await Publish(finance,Content("changed-head")with{Documents=[]});using(var denied=await customer.PostAsJsonAsync(Base(c3)+"/submissions/commands/"+Id(),Input(c3,current3)))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
    }
    [Fact]public async Task AuditFailureRollsBackSubmissionPointerVersionEventAndReceiptAndConcurrentRetryCommitsOnlyOnce()
    {
        using var finance=await Staff("FinanceManager");var person=await Customer();using var customer=person.Client;var(c,current)=await Consent(customer,finance);var path=Base(c);var id=Value(c["application"]!,"id");var command=Id();var input=Input(c,current);await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<IdentityContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_CreditSubmissionAuditFailure CHECK ([Action]<>'CREDIT_SUBMIT')");}
        try{using var failed=await customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_CreditSubmissionAuditFailure");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var app=await db.Applications.AsNoTracking().SingleAsync(x=>x.Id==id);Assert.Equal("Draft",app.State);Assert.Null(app.CurrentSubmissionId);Assert.Equal(input.ApplicationVersion,Convert.ToBase64String(app.Version));Assert.Empty(await db.Submissions.Where(x=>x.ApplicationId==id).ToArrayAsync());Assert.Empty(await db.SubmissionCommands.Where(x=>x.ApplicationId==id).ToArrayAsync());Assert.Equal(2,await db.ApplicationEvents.CountAsync(x=>x.ApplicationId==id));}
        var results=await Task.WhenAll((await Task.WhenAll(customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input),customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input))).Select(x=>Read(x)));Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());Assert.Single(results,x=>!x["replayed"]!.GetValue<bool>());using(var changed=await customer.PostAsJsonAsync(path+"/submissions/commands/"+command,input with{Note="different"}))Assert.Equal(HttpStatusCode.Conflict,changed.StatusCode);
        await using var final=sql.Factory.Services.CreateAsyncScope();var credit=final.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.Single(await credit.Submissions.Where(x=>x.ApplicationId==id).ToArrayAsync());var migrationSource=(await credit.Database.GetAppliedMigrationsAsync()).ToArray();var failure=await Assert.ThrowsAsync<SqlException>(()=>credit.GetService<IMigrator>().MigrateAsync("20261027001049_PrivateCreditDocuments"));Assert.Equal(51000,failure.Number);await credit.Database.MigrateAsync();Assert.Equal(migrationSource,await credit.Database.GetAppliedMigrationsAsync());Assert.False(credit.Database.HasPendingModelChanges());Assert.Single(await credit.Submissions.Where(x=>x.ApplicationId==id).ToArrayAsync());
    }
    [Fact]public async Task SubmitAndWithdrawalRaceHaveOneWinnerAndAChangedConsentCannotReuseTheOldSubmissionInput()
    {
        using var finance=await Staff("FinanceManager");var person=await Customer();using var customer=person.Client;var(c,current)=await Consent(customer,finance);var path=Base(c);var input=Input(c,current);var responses=await Task.WhenAll(customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),input),customer.PutAsJsonAsync(path+"/cancel/"+Id(),new CancelCreditApplicationInput(input.ApplicationVersion)));Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(responses,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var response in responses)response.Dispose();
        var id=Value(c["application"]!,"id");await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var app=await db.Applications.AsNoTracking().SingleAsync(x=>x.Id==id);var count=await db.Submissions.CountAsync(x=>x.ApplicationId==id);Assert.Equal(app.State=="Submitted"?1:0,count);Assert.Equal(3,await db.ApplicationEvents.CountAsync(x=>x.ApplicationId==id));}
        var(c2,current2)=await Consent(customer,finance);var oldInput=Input(c2,current2);var fresh=(await Publish(finance,Content("replacement-consent")with{Documents=[]}))["current"]!;var accepted=await Read(await customer.PostAsJsonAsync(Base(c2)+"/consents/"+Id(),Acceptance(c2["application"]!,fresh)));using(var stale=await customer.PostAsJsonAsync(Base(c2)+"/submissions/commands/"+Id(),oldInput))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);await Read(await customer.PostAsJsonAsync(Base(c2)+"/submissions/commands/"+Id(),Input(accepted,fresh)));
    }
    [Fact]public async Task OptionalDocumentsDoNotBecomeMandatoryButMissingConsentAndFalseReviewIntentAlwaysBlockSubmission()
    {
        using var finance=await Staff("FinanceManager");var person=await Customer();using var customer=person.Client;var current=(await Publish(finance,Content("optional")with{Documents=Content().Documents.Select(x=>x with{Required=false}).ToArray()}))["current"]!;var app=await Draft(customer);var path="/api/credit/applications/"+Value(app,"id");var blocked=await Read(await customer.GetAsync(path+"/submission"));Assert.False(blocked["canSubmit"]!.GetValue<bool>());Assert.Contains("credit_current_consent_required",blocked["blockers"]!.AsArray().Select(x=>x!.GetValue<string>()));var accepted=await Read(await customer.PostAsJsonAsync(path+"/consents/"+Id(),Acceptance(app,current)));var ready=await Read(await customer.GetAsync(path+"/submission"));Assert.True(ready["canSubmit"]!.GetValue<bool>());Assert.Equal(0,ready["selectedDocumentCount"]!.GetValue<int>());using(var falseIntent=await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),Input(accepted,current)with{ReviewRequested=false}))Assert.Equal(HttpStatusCode.BadRequest,falseIntent.StatusCode);using(var stale=await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),Input(accepted,current)with{ApplicationVersion=Value(app,"version")}))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);await Read(await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),Input(accepted,current)));
    }
    [Fact]public async Task SnapshotUsesOnlyLatestExplicitReplacementInTheAcceptedConsentAndRejectsCrossCaseLinks()
    {
        var store=new PrivateFileSqlTests.Store();using var factory=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(s=>{s.RemoveAll<IPrivateFileStore>();s.AddSingleton<IPrivateFileStore>(store);s.RemoveAll<IPrivateFileScanner>();s.AddSingleton<IPrivateFileScanner>(new PrivateFileSqlTests.Scan());}));var person=await Customer();using var original=person.Client;using var customer=factory.CreateClient(new(){HandleCookies=false});customer.DefaultRequestHeaders.Authorization=original.DefaultRequestHeaders.Authorization;customer.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");using var finance=await Staff("FinanceManager");var(c,current)=await Consent(customer,finance,true);var path=Base(c);
        async Task<JsonNode> Upload(string version,string? replacement,string marker){var bytes=Encoding.UTF8.GetBytes("%PDF-1.7\nSynthetic submission QA "+marker+"\n%%EOF\n");using var form=new MultipartFormDataContent();foreach(var(k,v)in new Dictionary<string,string>{["version"]=version,["consentId"]=Value(c["consent"]!,"id"),["requirementsRevisionId"]=Value(current["published"]!,"id"),["documentKey"]="sample-proof",["replacesFileId"]=replacement??"",["sha256"]=PrivateFileRules.Hash(bytes)})form.Add(new StringContent(v),k);var file=new ByteArrayContent(bytes);file.Headers.ContentType=new("application/pdf");form.Add(file,"file","Synthetic-"+marker+".pdf");return await Read(await customer.PostAsync(path+"/documents/commands/"+Id(),form));}
        var first=await Upload(Value(c["application"]!,"version"),null,"one");var last=await Upload(Value(first["application"]!,"version"),Value(first["attachment"]!,"id"),"two");var input=Input(c,current)with{ApplicationVersion=Value(last["application"]!,"version")};var submitted=await Read(await customer.PostAsJsonAsync(path+"/submissions/commands/"+Id(),input));var subId=Value(submitted["submission"]!,"id");var detail=await Wire(await customer.GetAsync(path+"/submissions/"+subId),"document-snapshot");Assert.Single(detail["documents"]!.AsArray());Assert.Equal(Value(last["attachment"]!,"id"),Value(detail["documents"]![0]!,"attachmentId"));Assert.Equal("Synthetic-two.pdf",Value(detail["documents"]![0]!["file"]!,"filename"));var page=await Read(await customer.GetAsync(path+"/documents"));Assert.False(page["canUpload"]!.GetValue<bool>());Assert.Contains("application_submitted",page["blockers"]!.AsArray().Select(x=>x!.GetValue<string>()));
        var another=await Draft(customer);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var otherId=Value(another,"id");var failure=await Assert.ThrowsAsync<SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[SubmissionDocuments] SET [ApplicationId]={otherId} WHERE [SubmissionId]={subId}"));Assert.Equal(547,failure.Number);Assert.Equal(2,store.Objects.Count);
    }
